export const usageSyncResultV1Schema = defineContractSchema({
  $schema: "https://json-schema.org/draft/2020-12/schema",
  $id: "https://schemas.viberacing.example/v1/usage-sync-result.schema.json",
  title: "UsageSyncResultV1",
  description:
    "Non-sensitive acknowledgement for one validated provider-neutral usage synchronization. Derived provider and private anomaly reasons are intentionally absent; an optional coarse recovery action carries no internal cause.",
  type: "object",
  additionalProperties: false,
  "x-viberacing-optionalProperties": ["nextAllowedSyncAt", "recoveryAction"],
  required: ["schemaVersion", "requestId", "syncId", "outcome", "acceptedEntries"],
  properties: {
    schemaVersion: {
      type: "integer",
      const: 1,
      minimum: 1,
      maximum: 1,
    },
    requestId: {
      type: "string",
      minLength: 26,
      maxLength: 26,
      pattern: "^req_[A-Za-z0-9_-]{22}$",
    },
    syncId: {
      type: "string",
      minLength: 26,
      maxLength: 26,
      pattern: "^syn_[A-Za-z0-9_-]{22}$",
    },
    outcome: {
      type: "string",
      enum: ["accepted", "duplicate", "quarantined"],
      minLength: 8,
      maxLength: 11,
    },
    acceptedEntries: {
      type: "integer",
      minimum: 0,
      maximum: 31,
    },
    nextAllowedSyncAt: {
      type: "string",
      minLength: 24,
      maxLength: 24,
      pattern: "^20[0-9]{2}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:00\\.000Z$",
      format: "date-time",
    },
    recoveryAction: {
      type: "string",
      enum: ["update_connector", "reconnect_account", "contact_support", "retry_later"],
      minLength: 11,
      maxLength: 17,
    },
  },
} as const satisfies ContractSchema);

export function validateUsageSyncResultV1(value: unknown): ValidationResult<UsageSyncResultV1> {
  return validateContract<UsageSyncResultV1>(usageSyncResultV1Schema, value);
}

export interface UsageSyncV1 {
  readonly schemaVersion: 1;
  readonly agentAccountId: string;
  readonly syncId: string;
  readonly observedAt: string;
  readonly clientVersion: string;
  readonly readerVersion: string;
  readonly dailyEntries: readonly {
    readonly usageDate: string;
    readonly dailyTokenTotal: string;
  }[];
}

export const usageSyncV1Schema = defineContractSchema({
  $schema: "https://json-schema.org/draft/2020-12/schema",
  $id: "https://schemas.viberacing.example/v1/usage-sync.schema.json",
  title: "UsageSyncV1",
  description:
    "Bounded provider-neutral Community usage submitted by one AgentAccount-bound device. Provider attribution, accounting revision, ranking, and trust fields are server-owned and intentionally absent.",
  type: "object",
  additionalProperties: false,
  required: [
    "schemaVersion",
    "agentAccountId",
    "syncId",
    "observedAt",
    "clientVersion",
    "readerVersion",
    "dailyEntries",
  ],
  properties: {
    schemaVersion: {
      type: "integer",
      const: 1,
      minimum: 1,
      maximum: 1,
    },
    agentAccountId: {
      type: "string",
      minLength: 26,
      maxLength: 26,
      pattern: "^acc_[A-Za-z0-9_-]{22}$",
    },
    syncId: {
      type: "string",
      minLength: 26,
      maxLength: 26,
      pattern: "^syn_[A-Za-z0-9_-]{22}$",
    },
    observedAt: {
      type: "string",
      minLength: 24,
      maxLength: 24,
      pattern: "^20[0-9]{2}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{3}Z$",
      format: "date-time",
    },
    clientVersion: {
      type: "string",
      minLength: 5,
      maxLength: 64,
      pattern: "^[0-9]+\\.[0-9]+\\.[0-9]+(?:-[0-9A-Za-z.-]+)?(?:\\+[0-9A-Za-z.-]+)?$",
    },
    readerVersion: {
      type: "string",
      minLength: 3,
      maxLength: 64,
      pattern: "^[a-z][a-z0-9_]{2,63}$",
    },
    dailyEntries: {
      type: "array",
      minItems: 1,
      maxItems: 31,
      "x-viberacing-uniqueBy": "usageDate",
      items: {
        type: "object",
        additionalProperties: false,
        required: ["usageDate", "dailyTokenTotal"],
        properties: {
          usageDate: {
            type: "string",
            minLength: 10,
            maxLength: 10,
            pattern: "^20[0-9]{2}-[0-9]{2}-[0-9]{2}$",
            format: "date",
          },
          dailyTokenTotal: {
            type: "string",
            minLength: 1,
            maxLength: 30,
            pattern: "^(?:0|[1-9][0-9]{0,29})$",
          },
        },
      },
    },
  },
} as const satisfies ContractSchema);

export function validateUsageSyncV1(value: unknown): ValidationResult<UsageSyncV1> {
  return validateContract<UsageSyncV1>(usageSyncV1Schema, value);
}
